from collections import Counter, deque
program = '''from collections import Counter, deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    noise = set()
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and g[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            if len(comp) == 1:
                noise.add(color)
    counts = Counter(v for row in g for v in row)
    noise = {v for v in noise if counts[v] <= max(6, h*w//20)}
    for r in range(h):
        for c in range(w):
            if g[r][c] in noise:
                ns = [g[y][x] for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0 <= y < h and 0 <= x < w and g[y][x] not in noise]
                if ns:
                    g[r][c] = Counter(ns).most_common(1)[0][0]
    return g
'''
